            'blocks' => [
                ['type' => 'graded_quiz', 'content' => ['questions' => [
                    ['question' => 'What is the main driver of strong vocabulary growth in each of a bilingual child\'s languages?', 'options' => [['text' => 'The amount of rich, real interaction the child gets in that language', 'correct' => true], ['text' => 'Whether the child was born in the country where the language is spoken', 'correct' => false], ['text' => 'Strict separation of the languages at all times', 'correct' => false], ['text' => 'Avoiding books and reading in the weaker language', 'correct' => false]], 'explanation' => 'Vocabulary growth in any language, bilingual or not, tracks the quantity and quality of real interaction a child receives in that language.'],
                    ['question' => 'If a family wants to strengthen a home language that gets less exposure than the community language, what is a realistic strategy?', 'options' => [['text' => 'Deliberately increase rich interaction time in the home language, such as stories, songs, and conversation', 'correct' => true], ['text' => 'Stop using the community language entirely', 'correct' => false], ['text' => 'Wait until the child is older to introduce the home language', 'correct' => false], ['text' => 'Rely only on occasional visits to relatives who speak it', 'correct' => false]], 'explanation' => 'Deliberately increasing quality interaction time, not eliminating the other language, is the evidence-based way to strengthen a less-exposed home language.'],
                    ['question' => 'A grandparent says the child should "just focus on one language for now." What does current guidance support?', 'options' => [['text' => 'There is no evidence that dropping a language benefits development, and it can cost family connection', 'correct' => true], ['text' => 'The grandparent is correct and bilingualism should be delayed until school age', 'correct' => false], ['text' => 'Only the mother\'s language should be kept', 'correct' => false], ['text' => 'Bilingual exposure should stop until any speech concern is resolved', 'correct' => false]], 'explanation' => 'Mainstream developmental guidance does not support dropping a home language for typically developing or even delayed children; bilingual exposure can continue alongside any needed support.'],
